CREATE OR REPLACE FUNCTION public.rollback_change(p_log_id integer)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_operation VARCHAR;
    v_table_name VARCHAR;
    v_record_id INTEGER;
    v_old_data JSONB;
    v_new_data JSONB;
    v_is_rolled_back BOOLEAN;
BEGIN
    -- Получаем данные из лога
    SELECT operation, table_name, record_id, old_data, new_data, is_rolled_back
    INTO v_operation, v_table_name, v_record_id, v_old_data, v_new_data, v_is_rolled_back
    FROM audit_log
    WHERE log_id = p_log_id;

    IF v_operation IS NULL THEN
        RAISE EXCEPTION 'Log entry with log_id % not found', p_log_id;
    END IF;

    IF v_is_rolled_back THEN
        RAISE EXCEPTION 'Log entry with log_id % has already been rolled back', p_log_id;
    END IF;

    -- Устанавливаем флаг, чтобы триггер не срабатывал
    PERFORM set_config('tgid.is_rollback', 'true', TRUE);

    -- Выполняем откат
    IF v_operation = 'INSERT' THEN
        EXECUTE format('DELETE FROM %I WHERE id = %s', v_table_name, v_record_id);
    ELSIF v_operation = 'UPDATE' THEN
        EXECUTE format('UPDATE %I SET %s WHERE id = %s',
                       v_table_name,
                       (SELECT string_agg(quote_ident(key) || ' = ' || quote_nullable(value), ', ')
                        FROM jsonb_each_text(v_old_data)),
                       v_record_id);
    ELSIF v_operation = 'DELETE' THEN
        EXECUTE format('INSERT INTO %I (%s) VALUES (%s)',
                       v_table_name,
                       (SELECT string_agg(quote_ident(key), ', ') FROM jsonb_object_keys(v_old_data) AS t(key)),
                       (SELECT string_agg(quote_nullable(value), ', ') FROM jsonb_each_text(v_old_data) ));
    END IF;

    -- Помечаем как откатанное
    UPDATE audit_log SET is_rolled_back = TRUE WHERE log_id = p_log_id;

    -- Сбрасываем флаг
    PERFORM set_config('tgid.is_rollback', 'false', TRUE);

    RAISE NOTICE 'Rollback for log_id % on table % completed and marked as rolled back', p_log_id, v_table_name;
EXCEPTION
    WHEN OTHERS THEN
        -- Сбрасываем флаг в случае ошибки
        PERFORM set_config('tgid.is_rollback', 'false', TRUE);
        RAISE EXCEPTION 'Rollback failed for log_id %: %', p_log_id, SQLERRM;
END;
$function$

CREATE OR REPLACE FUNCTION public.rollback_group(p_group_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    rec RECORD;
BEGIN
    -- Устанавливаем флаг, чтобы триггер не срабатывал
    PERFORM set_config('tgid.is_rollback', 'true', TRUE);

    -- Откатываем записи в обратном порядке
    FOR rec IN
        SELECT log_id
        FROM audit_log
        WHERE change_group_id = p_group_id AND is_rolled_back = FALSE
        ORDER BY changed_at DESC
    LOOP
        PERFORM rollback_change(rec.log_id);
    END LOOP;

    -- Сбрасываем флаг
    PERFORM set_config('tgid.is_rollback', 'false', TRUE);

    RAISE NOTICE 'Rollback for group % completed', p_group_id;
EXCEPTION
    WHEN OTHERS THEN
        -- Сбрасываем флаг в случае ошибки
        PERFORM set_config('tgid.is_rollback', 'false', TRUE);
        RAISE EXCEPTION 'Group rollback failed for group %: %', p_group_id, SQLERRM;
END;
$function$

CREATE OR REPLACE FUNCTION public.shape_to_coord(list text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    pos     int := 1;
    len     int;
    value   text;
    value2  numeric;
    out     text := '';
    even    boolean := false;
BEGIN
    IF list IS NULL OR list = '' THEN
        RETURN '';
    END IF;

    -- Удаление лишнего
    list := replace(list, 'LINESTRING (', '');
    list := replace(list, ')', '');
    list := replace(list, ',', ' ');
    list := regexp_replace(list, '\s+', ' ', 'g');
    list := trim(list);

    -- Удалить первые и последние две координаты
    list := remove_head(list);
    list := remove_head(list);
    list := reverse(list);
    list := remove_head(list);
    list := remove_head(list);
    list := reverse(list);

    list := list || ' ';

    WHILE position(' ' IN list) > 0 LOOP
        len := position(' ' IN list);
        value := substr(list, 1, len - 1);
        list := substr(list, len + 1);

        BEGIN
            value2 := value::numeric * 100;
        EXCEPTION WHEN others THEN
            CONTINUE;
        END;

        IF NOT even THEN
            even := true;
        ELSE
            even := false;
            value2 := -value2;
        END IF;

        IF out = '' THEN
            out := value2::text;
        ELSE
            IF even THEN
                out := out || ',' || value2::text;
            ELSE
                out := out || ' ' || value2::text;
            END IF;
        END IF;
    END LOOP;

    RETURN out || ',';
END;
$function$

CREATE OR REPLACE FUNCTION public.str_coords(list1 character varying)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$

DECLARE 
    pos INT;
    pos2 INT;
    len1 INT;
    len2 INT;

    value1 varchar;
    value2 decimal(20,2);
    limit1 varchar;
    limit2 varchar;
