CREATE OR REPLACE FUNCTION public.str_coords_x(list1 character varying)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
    numbers TEXT[]; -- Array to hold split numbers
    x_val NUMERIC; -- X-coordinate
    y_val NUMERIC; -- Y-coordinate
    formatted_pair TEXT; -- Formatted x y pair
    out1 VARCHAR := ''; -- Output string
    i INT; -- Loop counter
BEGIN
    -- Handle empty or NULL input
    IF list1 IS NULL OR TRIM(list1) = '' THEN
        RETURN '';
    END IF;

    -- Replace commas with spaces and normalize whitespace
    list1 := REGEXP_REPLACE(TRIM(REPLACE(list1, ',', ' ')), '\s+', ' ');
    numbers := REGEXP_SPLIT_TO_ARRAY(list1, ' ');

    -- Check if number count is even (valid pairs)
    IF ARRAY_LENGTH(numbers, 1) % 2 != 0 THEN
        RAISE EXCEPTION 'Input must have an even number of values for x-y pairs: %', list1;
    END IF;

    -- Loop through numbers two at a time (x, y pairs)
    FOR i IN 1..ARRAY_LENGTH(numbers, 1) BY 2 LOOP
        -- Validate that both x and y are valid numbers (integer or decimal)
        IF numbers[i] ~ '^-?[0-9]+(\.[0-9]+)?$' AND numbers[i+1] ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
            x_val := CAST(numbers[i] AS NUMERIC) / 100;
            y_val := CAST(numbers[i+1] AS NUMERIC) / 100;

            -- Format pair to two decimal places
            formatted_pair := TO_CHAR(x_val, 'FM99999999999999999990.99') || ' ' ||
                             TO_CHAR(-y_val, 'FM99999999999999999990.99');

            -- Build output string
            IF out1 = '' THEN
                out1 := formatted_pair;
            ELSE
                out1 := out1 || ',' || formatted_pair;
            END IF;
        ELSE
            RAISE EXCEPTION 'Invalid numeric value at position % or %: % or % (input: %)', 
                i, i+1, numbers[i], numbers[i+1], list1;
        END IF;
    END LOOP;

    IF out1 != '' THEN
        out1 := out1 || ',';
    END IF;


    RETURN out1;
END;
$function$

